const body = $input.first().json.body || $input.first().json;
const content = (body.content || '').trim();
const channel_id = body.channel_id || (body.message ? body.message.channel_id : '');
const author = body.author || (body.message ? body.message.author : {});
const message_id = body.id || (body.message ? body.message.id : String(Date.now()));
const mentionsLucas = /lucas/i.test(content);
const mentionsHermes = /hermes/i.test(content);
const author_name = (author.username || author.globalName || author.id || 'unknown');
let route = 'lucas';
if (channel_id === '1506239471325020327' && !mentionsLucas && !mentionsHermes) {
  route = 'secretary';
}
if (mentionsHermes) { route = 'hermes'; }
if (mentionsLucas) { route = 'lucas'; }
let profile = 'brain';
if (route === 'secretary') { profile = 'secretary'; }
return [{
  json: {
    content: content,
    channel_id: channel_id,
    author_name: author_name,
    author_id: (author.id || ''),
    message_id: message_id,
    route: route,
    profile: profile,
    taskId: 'n8n-' + (message_id || Date.now())
  }
}];

const resp = $input.first().json;
const ch = $json.channel_id || '';
let raw = '';
if (resp.status === 'success') {
  raw = resp.data;
  const ag = resp.agent && resp.agent !== 'llm' ? '[' + resp.agent + '] ' : '';
  const tm = resp.elapsed ? ' (' + Math.round(resp.elapsed / 1000) + 's)' : '';
  raw = ag + raw.trim() + tm;
} else { raw = '处理失败: ' + (resp.data || '未知错误'); }
if (!raw) return [{json:{content:'回复为空',channel_id:ch}}];
const MAX=1900,s=[];let r=raw;
while(r.length>MAX){
  let c=MAX;
  let se=Math.max(r.lastIndexOf('。',c),r.lastIndexOf('！',c),r.lastIndexOf('？',c));
  if(se>MAX*0.4){c=se+1;}else{let sp=Math.max(r.lastIndexOf(' ',c),r.lastIndexOf('，',c));if(sp>MAX*0.2){c=sp+1;}}
  s.push(r.slice(0,c).trim());r=r.slice(c).trim();
}
if(r)s.push(r);
if(s.length>1)return s.map((x,i)=>({json:{content:(i+1)+'/'+s.length+' '+x,channel_id:ch}}));
return[{json:{content:s[0],channel_id:ch}}];
